<script setup>
import {ref,onMounted} from 'vue';import {api,jsonBody} from '../api';import {hasPermission} from '../auth';import {showConfirm} from '../uiDialogs';
defineProps({students:{type:Array,default:()=>[]}});
const batches=ref([]),reports=ref([]),reason=ref(''),error=ref(''),busy=ref(false);
async function load(){try{if(hasPermission('rankings.batches.read'))batches.value=await api('/rankings/admin/operations/import-batches');if(hasPermission('rankings.reconciliation.read'))reports.value=await api('/rankings/admin/operations/reconciliations');}catch(e){error.value=e.message;}}
async function run(){if(busy.value)return;busy.value=true;error.value='';try{await api('/rankings/admin/operations/reconciliations',{method:'POST'});await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function reverse(batch){if(!reason.value.trim()){error.value='请先填写撤销原因';return;}if(!await showConfirm(`撤销批次 ${batch.id}？积分不足或已被覆盖时将整批拒绝。`))return;busy.value=true;error.value='';try{await api(`/rankings/admin/operations/import-batches/${batch.id}/reverse`,{method:'POST',body:jsonBody({reason:reason.value})});await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}

async function repair(r){if(!reason.value.trim()){error.value='请填写修复原因';return;}if(!await showConfirm('按核实后的业务余额修复台账？这不会改变学生可用积分。'))return;busy.value=true;error.value='';try{await api('/rankings/admin/operations/reconciliations/repair',{method:'POST',body:jsonBody({studentId:r.student_id,expectedSource:r.source_balance,expectedLedger:r.ledger_balance,reason:reason.value})});await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section class="points-ops"><label v-if="hasPermission('rankings.reconciliation.repair')">台账修复原因<input v-model="reason" maxlength="255" placeholder="核实业务来源后填写原因"></label><p v-if="error" class="notice notice-error" role="alert">{{error}}</p><section v-if="hasPermission('rankings.reconciliation.read')||hasPermission('rankings.reconciliation.run')"><h2>积分对账</h2><p>每日凌晨自动核对，异常不会自动改分。请核实来源后，通过积分调整填写原因处理。</p><button v-if="hasPermission('rankings.reconciliation.run')" class="button button-primary" :disabled="busy" @click="run">执行对账</button><div class="ops-table"><table><thead><tr><th>学员 ID</th><th>业务余额</th><th>流水余额</th><th>结果</th><th>检查时间</th></tr></thead><tbody><tr v-for="r in reports" :key="r.id"><td>{{r.student_id}}</td><td>{{r.source_balance}}</td><td>{{r.ledger_balance}}</td><td>{{r.result==='OK'?'一致':'需核查'}}<button v-if="r.result!=='OK'&&hasPermission('rankings.reconciliation.repair')" class="button button-quiet" :disabled="busy" @click="repair(r)">修复台账</button></td><td>{{new Date(r.checked_at).toLocaleString('zh-CN')}}</td></tr></tbody></table></div></section><section v-if="hasPermission('rankings.batches.read')"><h2>导入批次</h2><label v-if="hasPermission('rankings.import.reverse')">撤销原因<input v-model="reason" maxlength="255" placeholder="填写撤销原因后，选择需要撤销的批次"></label><div class="ops-table"><table><thead><tr><th>批次</th><th>来源</th><th>状态</th><th>更新 / 拒绝</th><th>导入时间</th><th>操作</th></tr></thead><tbody><tr v-for="b in batches" :key="b.id"><td>{{b.id}}</td><td>{{b.source_name}}</td><td>{{b.status}}</td><td>{{b.changed_rows}} / {{b.rejected_rows}}</td><td>{{new Date(b.created_at).toLocaleString('zh-CN')}}</td><td><button v-if="hasPermission('rankings.import.reverse')&&!b.reversed_at" class="button button-quiet" :disabled="busy" @click="reverse(b)">撤销批次</button></td></tr></tbody></table></div></section></section></template>
<style scoped>.points-ops{min-width:0;max-width:100%;display:grid;gap:24px;padding:20px;background:white;border:1px solid #d8e0e3;border-radius:10px}.points-ops>section{min-width:0;max-width:100%}.points-ops h2{font-size:18px}.points-ops p{color:#637984}.ops-table{overflow:auto;margin-top:14px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #e3e9eb;white-space:nowrap}select,input{padding:9px;border:1px solid #d8e0e3;border-radius:6px;max-width:100%}label{display:flex;flex-wrap:wrap;gap:12px;align-items:center}input{min-width:0;flex:1 1 180px}</style>
